 "content": "def transform(grid):
    """Find the repeated 3x3 symbol in the grid and recolor its pixels 8."""
    n, m = len(grid), len(grid[0])
    best = None
    # Enumerate ordinary 3x3 regions and select the one with the greatest
    # number of occurrences of any single color (excluding background).
    for r in range(n - 2):
        for c in range(m - 2):
            counts = {}
            for i in range(3):
                for j in range(3):
                    v = grid[r+i][c+j]
                    if v:
                        counts[v] = counts.get(v, 0) + 1
            for color, score in counts.items():
                if best is None or score > best[0]:
                    mask = [[int(grid[r+i][c+j] == color) for j in range(3)] for i in range(3)]
                    best = score, mask
    return [[8 * v for v in row] for row in best[1]]

if __name__ == '__main__':
    demos = [
