    from collections import Counter
    n, m = len(grid), len(grid[0])
    color = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    # The demos encode the same small pattern with different skew/orientation.
    # Search small affine 3x3 lattices and select the one with the most hits
    # of the dominant color; tie-break toward compact, near-unit vectors.
    best = None
    vectors = [(dr, dc) for dr in range(-2, 3) for dc in range(-2, 3) if (dr, dc) != (0, 0)]
    for r in range(n):
        for c in range(m):
            for vr in vectors:
                for vc in vectors:
                    # lattice vectors must span a 2D region
                    if vr[0]*vc[1] - vr[1]*vc[0] == 0:
                        continue
                    coords = [[(r+i*vr[0]+j*vc[0], c+i*vr[1]+j*vc[1]) for j in range(3)] for i in range(3)]
                    if not all(0 <= rr < n and 0 <= cc < m for row in coords for rr,cc in row):
                        continue
                    mask = [[int(grid[rr][cc] == color) for rr,cc in row] for row in coords]
                    score = sum(map(sum, mask))
                    compact = sum(abs(x) for x in vr+vc)
                    key = (score, -compact)
                    if best is None or key > best[0]:
                        best = (key, mask)
    return [[8*x for x in row] for row in best[1]]

